function escapeHtml(value:string){return value.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function formatBytes(value:number){return value<1024?`${value} B`:value<1024*1024?`${(value/1024).toFixed(1)} KB`:`${(value/1024/1024).toFixed(1)} MB`}
function colorBatch(picked:Picked,changes:Record<string,string>){const bySelector=new Map<string,Record<string,string>>();for(const group of picked.colorGroups){const color=changes[group.value];if(!color)continue;for(const use of group.uses){const selector=use.sourceSelector||use.selector,styles=bySelector.get(selector)||{};for(const property of use.properties)styles[property]=color;bySelector.set(selector,styles)}}return[...bySelector].map(([selector,styles])=>({selector,styles}))}
